// Nine EX hunts from rank 20 through 100; rank 100 is the repeatable final encounter.
const EX_NAMES=['鋼嵐の覇者','深海の災厄','熔星の巨神','虚空の双牙','死界の帝王','千雷の審判者','星滅の龍','終末の観測者','原初の終焉アザレク'];
const EX_BOSSES=EX_NAMES.map((name,i)=>{let rank=20+i*10,s={id:'ex'+rank,name,region:rank===20?9:rank===30?10:11,role:4+i%4,boss:true,index:3,exRank:rank};SPECIES[s.id]=s;for(let [tier,t]of MATERIAL_TIERS.entries())MATERIALS[s.id+':'+tier]={id:s.id+':'+tier,species:s.id,tier,name:s.name+'の'+t.part,color:t.color};return s});
const advancedCampaignBase=campaign;campaign=()=>{let c=advancedCampaignBase();c.rank??=Math.min(10,c.unlocked+1);return c};
function rankRegion(rank){return rank<10?rank-1:rank<20?9:rank<30?10:11}
function showExResult(){
 let c=campaign(),r=c.lastEx;if(!villageOpen||!r)return false;let spec=SPECIES[r.species],owned=c.materials[r.species+':0']||0;
 worldMenu('EX挑戦の結果','<h3>EX'+spec.exRank+' · '+spec.name+'</h3><div class="dps-results"><div><small>今回削ったHP</small><strong>'+(r.units/100).toFixed(2)+'%</strong></div><div><small>獲得した欠片</small><strong>+'+r.count+'</strong></div></div><p>'+(r.defeated?'討伐成功 · 討伐ボーナス50個を含む':r.count?'帰還・敗北でも素材を獲得':'1%未満のため、今回の欠片は0個')+'</p><p>欠片の現在所持数：'+owned+'個</p>'+(spec.exRank===100?'<p>'+(owned>=50?'終焉装備を製作できます（欠片50個）':'終焉装備の製作まで、あと'+(50-owned)+'個')+'</p><button onclick="openFinalForge()">終焉装備の工房へ</button><button onclick="panel(\'inventory\')">装備を比較・強化</button>':'')+'<button onclick="showVillage()">依頼掲示板へ</button>','exResult');return true;
}
function openFinalForge(){if(!villageOpen||!endgameUnlocked())return false;worldForgeSpecies='ex100';worldForgeTier=0;showForge();return true}
function veteranXP(rank){return 100+rank*8}
const ordinaryGuildQuest=guildQuest;guildQuest=id=>{if(typeof id==='string'&&id.startsWith('ex:')){let s=SPECIES[id.slice(3)];return s?.exRank?{id,kind:'ex',target:s.id,region:s.region,required:1,xp:180+s.exRank*5,name:'EX'+s.exRank+'：'+s.name}:null}return ordinaryGuildQuest(id)};
function guildQuestEligible(q,c,history=false){
 if(!q||q.region>c.unlocked)return false;
 if(!history&&!c.questDone.length)return q.id==='hunt:r0e0';
 if(q.kind==='ex')return c.rank>=SPECIES[q.target].exRank;
 if(q.kind==='trial')return q.region<9&&(history?q.region<c.rank-1:c.rank<10&&q.region===c.rank-1&&c.rankXP>=promotionXP(c.rank));
 if(q.kind==='secret')return c.rank>q.region+1;
 return true;
}
guildQuestAllowed=q=>guildQuestEligible(q,campaign());
claimContract=()=>{let c=campaign(),q=c.contract;if(!villageOpen||!q?.killed)return false;let spec=SPECIES[q.target],quest=guildQuest(q.id||'boss:'+q.target);if(!quest||!guildQuestEligible(quest,c))return false;let rankBefore=c.rank;
 if(!worldTransaction(()=>{if(!c.questDone.includes(quest.id)){c.questDone.push(quest.id);p.points+=quest.kind==='hunt'?1:2}if(spec.boss&&!c.completed.includes(spec.id))c.completed.push(spec.id);p.gold+=80+spec.region*50;c.rankXP+=quest.xp;if(quest.kind==='trial'&&c.rank<10&&quest.region===c.rank-1){c.rankXP-=promotionXP(c.rank);c.rank++}if(c.rank>=10)while(c.rank<100&&c.rankXP>=veteranXP(c.rank)){c.rankXP-=veteranXP(c.rank);c.rank++}c.unlocked=rankRegion(c.rank);c.contract=null}))return false;showVillage();if(c.rank>rankBefore)say('冒険者ランク '+c.rank+'！'+(c.rank%10===0?' 新しいEX依頼を確認しよう':''));return true;
};
const advancedValidate=validateSave;validateSave=data=>{let out=advancedValidate(data);if(!out.p.campaign)return out;let c=out.p.campaign,src=data.p.campaign;c.rank=src.rank??Math.min(10,c.unlocked+1);if(!Number.isInteger(c.rank)||c.rank<1||c.rank>100||c.unlocked!==rankRegion(c.rank))throw Error('冒険者ランクと地域が一致しません');if(c.contract&&!guildQuestEligible(guildQuest(c.contract.id),c))throw Error('依頼の受注条件を満たしていません');if(c.questDone.some(id=>!guildQuestEligible(guildQuest(id),c,true)))throw Error('未解放の依頼履歴があります');if(c.completed.some(id=>{let spec=SPECIES[id];return !guildQuestEligible(guildQuest((spec.exRank?'ex:':spec.secret?'secret:':'boss:')+id),c,true)}))throw Error('未解放のボス討伐履歴があります');return out};
// Tuned against the level-50 six-link stationary benchmark; actual combat includes evasion and downtime.
const FINAL_BOSS_HEALTH_FACTOR=32;
const advancedSpawn=spawnSpecies;spawnSpecies=(spec,x,y)=>{let e=advancedSpawn(spec,x,y);if(e&&spec.exRank){e.exRank=spec.exRank;e.hp*=Math.pow(spec.exRank/15,1.6)*(spec.exRank===100?FINAL_BOSS_HEALTH_FACTOR:1);e.max=e.hp;e.startMax=e.max;e.partialPaid=false}return e};
const advancedLoad=loadWorld;loadWorld=()=>{advancedLoad();let q=campaign().contract;if(!villageOpen&&q?.kind==='ex'&&SPECIES[q.target].region===worldRegion){let pos=center(BOSS_ARENAS[3].cx,BOSS_ARENAS[3].cy);enemies=enemies.filter(e=>e.species!==REGIONS[worldRegion].bosses[3].id);spawnSpecies(SPECIES[q.target],pos.x,pos.y)}};
// Pay only once per encounter, on retreat, death, or victory. No damage -> no material.
let exSettlementQueue=[];
function settleExMaterials(){let pending=[...new Set([...enemies,...exSettlementQueue])].filter(e=>e.exRank&&!e.partialPaid&&e.hp<e.max),awards=[];for(let e of pending){let fraction=clamp(1-Math.max(0,e.hp)/e.max,0,1),units=Math.floor((fraction+1e-9)*10000),count=Math.floor(units/100);if(e.hp<=0)count+=50;awards.push({e,id:e.species+':0',count,units})}if(!awards.length)return true;
 if(!worldTransaction(()=>{let c=campaign(),mats=c.materials;for(let a of awards){mats[a.id]=(mats[a.id]||0)+a.count;c.lastEx={species:a.e.species,units:a.units,count:a.count,defeated:a.e.hp<=0}}})){exSettlementQueue=awards.map(a=>a.e);return false}exSettlementQueue=[];for(let a of awards){a.e.partialPaid=true;if(a.count)feed(MATERIALS[a.id].name+' ×'+a.count+'（討伐・削り報酬）')}return true;
}
const advancedKill=worldKill;worldKill=e=>{if(!e)return;let rewarded=e.rewarded;advancedKill(e);if(!rewarded&&e.rewarded&&e.exRank)settleExMaterials()};
const advancedReturn=returnVillage;returnVillage=()=>{let showResult=!villageOpen&&[...enemies,...exSettlementQueue].some(e=>e.exRank&&e.hp<e.max);if(!settleExMaterials())return;advancedReturn();if(showResult&&villageOpen)showExResult()};
const advancedUpdate=update;update=dt=>{advancedUpdate(dt);if(dead)settleExMaterials()};
const advancedAttack=worldAttack;worldAttack=e=>{if(!e.exRank)return advancedAttack(e);let oldHurt=hurt,first=shots.length;hurt=d=>oldHurt(d*(1+e.exRank/50));try{advancedAttack(e)}finally{hurt=oldHurt}for(let s of shots.slice(first))s.damage*=1+e.exRank/50};
endgameUnlocked=()=>campaign().rank>=100;
const regionalForgeCost=forgeCost;forgeCost=(spec,tier,endgame=false)=>endgame?{['ex100:'+tier]:[50,3,2,1][tier]}:regionalForgeCost(spec,tier,false);
const advancedCraft=craftMaterialGear;craftMaterialGear=(endgame=false)=>{if(endgame&&worldForgeSpecies!=='ex100'){say('終焉製作にはEX100の素材を選んでください');return false}return advancedCraft(endgame)};
const advancedSaveItem=saveItem;saveItem=(it,expected)=>{let out=advancedSaveItem(it,expected);if(out&&it.forge==='endgame'){let n=it.forgeLevel??0;if(!Number.isInteger(n)||n<0||n>10)throw Error('終焉装備の強化値が不正です');out.forgeLevel=n}return out};
const regionalCraft=craft;craft=slot=>{let item=p[slot];if(item?.forge!=='endgame')return regionalCraft(slot);let level=item.forgeLevel||0,cost=20+level*10,mats=campaign().materials;if(!villageOpen){say('終焉装備の強化は村で行えます');return false}if(level>=10){say('強化上限 +10 です');return false}if((mats['ex100:0']||0)<cost){say('EX100の欠片が '+cost+' 個必要です');return false}if(!worldTransaction(()=>{mats['ex100:0']-=cost;item.forgeLevel=level+1;item.value=Math.ceil(item.value*1.05);for(let m of item.mods)m.value=Math.ceil(m.value*1.05)}))return false;panel('inventory');return true};
const endgameDetails=itemDetails;itemDetails=it=>endgameDetails(it)+(it.forge==='endgame'?'<small>終焉強化 +'+(it.forgeLevel||0)+' / 10 · 次回：欠片 '+(20+(it.forgeLevel||0)*10)+'個</small>':'');
const advancedVillage=showVillage;showVillage=(region=campaign().region)=>{advancedVillage(region);let c=campaign(),r=REGIONS[region]||REGIONS[0],heading=$('card').querySelector('h2');if(heading)heading.textContent='冒険者ギルド · ランク '+c.rank;let body=$('card').querySelector('.panel-body');if(!body)return;for(let button of Array.from(body.querySelectorAll('button')))if(button.getAttribute('onclick')?.includes("trial:")&&c.rank>=10)button.remove();if(c.rank>=10){let info=Array.from(body.querySelectorAll('p')).find(el=>el.textContent.startsWith('ランク経験値 '))||document.createElement('p');info.textContent='熟練ランクXP '+c.rankXP+' / '+(c.rank<100?veteranXP(c.rank):'最高ランク')+' · 以降は昇格試験なし。10ランクごとにEX解放';if(!info.parentElement)body.prepend(info)}let available=EX_BOSSES.filter(s=>s.exRank<=c.rank);if(available.length)body.insertAdjacentHTML('beforeend','<h3>EX討伐依頼</h3><div class="guild-quests">'+available.map(s=>'<button onclick="acceptGuildQuest(\'ex:'+s.id+'\')" '+(c.contract?'disabled':'')+'>EX'+s.exRank+' '+s.name+'<small>'+REGIONS[s.region].name+' · HPを1%削るごとに欠片1個、討伐で追加50個</small></button>').join('')+'</div>')};
const advancedDpsHud=drawHud;drawHud=()=>{advancedDpsHud();if(!p?.campaign)return;let q=campaign().contract;if(!villageOpen&&q&&!q.killed)hudText($('progress'),fieldQuestStatus().progress)};
const guildWelcomeBase=welcome;welcome=()=>{guildWelcomeBase();$('card').innerHTML=$('card').innerHTML.replace('朽ちた墓所の奥へ。亡者を斬り、遺物を集め、深淵の番人を倒せ。','灯火の村で冒険者に。討伐依頼を受け、素材で装備を作り、昇格試験とEXボスに挑もう。')};if(!started)welcome();
const guildHelpBase=panel;panel=kind=>{guildHelpBase(kind);if(kind==='help'&&p?.campaign)worldMenu('冒険者の手引き',"<h3>移動と戦闘</h3><p>WASD／左スティックで移動。マウス／右スティックで照準。通常攻撃はShift＋左クリック／ZR、回避はSpace／A。敵の予兆から離れ、攻撃後の隙を狙いましょう。</p><p>スキルはQ E R T Y U／Y・X・ZL＋Y/X/A/Bの6枠。1／Rで生命瓶、F／Bで拾う・調べる。Tab／−で地図、Esc／＋で一時停止・村への帰還。</p><h3>メニューの選び方</h3><p>左のアイコンを選ぶと右に詳細が表示されます。十字キーで一つずつ選択し、Aで右側の操作へ。もう一度Aで実行します。Bで一覧へ戻り、一覧でBを押すと画面を戻ります。</p><p>装備・ジェム・成長・倉庫はL/Rで切り替え。右スティックで説明をスクロールします。アイコンを選ぶだけでは装備変更や依頼の受注は行いません。</p><h3>依頼と昇格</h3><p>村の掲示板でF／B。左の依頼を選び、右の「この依頼を受注する」で出発します。最初は草牙狼8体の討伐から。地図の水色の印が依頼対象です。</p><p>討伐後は村に帰り、報告してランク経験値を受け取ります。必要経験値をためてボスの昇格試験に挑戦。ランク10以降は経験値で100まで上がり、EXボスは20・30・40…100で解放されます。</p><h3>素材と装備製作</h3><p>敵は専用素材を落とします。F／Bで回収して村の工房へ。地域・敵・装備部位・素材品質を選び、費用を確認して製作します。落ちている素材は帰還前に拾いましょう。</p><p>I／Lで装備画面。左の鞄アイコンを選ぶと右に性能と比較が表示され、右の「装備」で付け替えます。交換前の装備は鞄に戻ります。ジェムは元の装備に残ります。</p><h3>ジェムと6つのスキル</h3><p>Gでジェム画面。左でジェムを選び、右の「このジェムを装着する」を決定。同色または白のソケットへ装着します。赤R・緑G・青Bは入れられるジェムの色で、色自体に攻撃力の効果はありません。</p><p>左の「スキル枠1～6」を選び、右の選択欄で装備中のアクティブジェムを割り当てます。サポートは割り当て不要。同じリンク内の対応スキルに効きます。外した装備のジェムは使えません。</p><h3>属性反応</h3><p>敵のHPバー下の属性アイコンで付着を確認できます。異なる属性を重ねると、2属性・3属性の組み合わせに応じた反応が発生します。</p><p>ジェム画面の「ジェムの使い方・元素反応」から反応表を開けます。組み合わせと効果を確認して、スキルや属性変更・付加サポートを組みましょう。</p><h3>パッシブとセット効果</h3><p>Pでパッシブツリー。ノードを選ぶと右に効果が表示されます。取得済みノードに隣接するものを、成長ポイントで取得できます。</p><p>同じ装備タグは2・4・6・8部位で効果が発動します。鞄や倉庫の装備は数えません。装備詳細の「タグ効果」で必要数と固有効果を確認できます。</p><h3>EXと終焉装備</h3><p>EX100はHPを1%削るごとに欠片1個、討伐でさらに50個。帰還・敗北・討伐で精算します。倒しきれなくても削った分の素材を次の強化に使えます。</p><p>欠片50個で終焉装備を製作。ランダム効果を厳選し、装備画面から+10まで強化できます。タグの組み合わせも考えながら最終ボスに再挑戦しましょう。</p><h3>DPSと保存</h3><p>村の東側のサンドバッグで30秒DPSチャレンジ。結果画面で今回のDPSと端末内の自己ベストを確認できます。測定中にメニューを開くと中止されます。</p><p>進行はブラウザに自動保存されます。保存画面からJSONの書き出し・復元・履歴の確認ができます。別の端末やブラウザへ移る前に書き出してください。共有ランキングはサーバー接続が必要です。</p>",'help')};

const exResultValidate=validateSave;validateSave=data=>{let out=exResultValidate(data),r=data.p.campaign?.lastEx;if(r!==undefined){let spec=SPECIES[r?.species];if(!spec?.exRank||spec.exRank>out.p.campaign.rank||!Number.isInteger(r.units)||r.units<0||r.units>10000||typeof r.defeated!=='boolean'||r.defeated&&r.units!==10000||r.count!==Math.floor(r.units/100)+(r.defeated?50:0))throw Error('EX挑戦の記録が不正です');out.p.campaign.lastEx={species:r.species,units:r.units,count:r.count,defeated:r.defeated}}return out};
const exResultVillage=showVillage;showVillage=(...args)=>{exResultVillage(...args);if(campaign().lastEx)$('card').querySelector('.world-tabs')?.insertAdjacentHTML('beforeend','<button onclick="showExResult()">前回のEX結果</button>')};
